      if (b[1] !== a[1]) {
        return b[1] - a[1]; // Sort by count descending
      }
      return a[0].localeCompare(b[0]); // Sort alphabetically ascending for ties
    });

  // Output results
  for (const [word, count] of sortedEntries) {
    console.log(`${word}: ${count}`);
  }
