	testCases := []testCase{
		{
			description: "Quantity 9 (No Discount)",
			price:       10.0,
			quantity:    9,
			expected:    10.0 * 9, // 90.0
		},
		{
			description: "Quantity 10 (First Boundary - 10% Discount)",
			price:       10.0,
			quantity:    10,
