			price:       20.0,
			quantity:    50,
			expected:    20.0 * 50 * 0.75, // 750.0
		},
	}

	allPassed := true

	for _, tc := range testCases {
		result := calculateDiscount(tc.price, tc.quantity)

		// Use a small epsilon for float comparison to handle potential precision issues
