{
    if (isPrime[p])
    {
        for (int i = p * p; i <= n; i += p)
        {
            isPrime[i] = false;
        }
    }
}

// Collect and print primes
var primes = new List<int>();
for (int i = 2; i <= n; i++)
{
    if (isPrime[i])
    {
        primes.Add(i);
    }
}

